package com.zidio.keystone.controller;
import com.zidio.keystone.domain.*; import com.zidio.keystone.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/reports") @PreAuthorize("hasRole('MANAGER')") public class ReportController { final WorkOrderRepository w; final AppUserRepository users; public ReportController(WorkOrderRepository w,AppUserRepository users){this.w=w;this.users=users;} @GetMapping("/summary") public Map<String,Object> summary(){Map<String,Object> m=new LinkedHashMap<>();for(var x:WorkOrderStatus.values())m.put(x.name(),w.countByStatus(x));var terminal=List.of(WorkOrderStatus.CLOSED,WorkOrderStatus.CANCELLED);m.put("overdue",w.countBySlaDueAtBeforeAndStatusNotIn(Instant.now(),terminal));m.put("open",w.findByStatusIn(List.of(WorkOrderStatus.NEW,WorkOrderStatus.ASSIGNED,WorkOrderStatus.IN_PROGRESS,WorkOrderStatus.ON_HOLD,WorkOrderStatus.COMPLETED)).size());m.put("technicians",users.findByRole(Role.TECHNICIAN).stream().map(u->Map.of("name",u.getFullName(),"assigned",w.findByAssigneeIdOrderByCreatedAtDesc(u.getId(),org.springframework.data.domain.Pageable.unpaged()).getTotalElements())).toList());return m;}}
